// Package usgs ingests the USGS real-time earthquake feed.
//
// Feed: M2.5+ for the past day, GeoJSON, regenerated by USGS every minute
// (https://earthquake.usgs.gov/earthquakes/feed/v1.0/geojson.php). Polling
// it every 60 s matches the source's own cadence (ADR 16). The day window
// means every revision USGS makes within 24 h (magnitude, location, review
// status, PAGER alert) reaches us. The feed ignores conditional GET; the
// fetch client compares Last-Modified itself, so an unchanged minute costs
// one ~4 KB gzip download and nothing else.
//
// Public domain (U.S. Government work); attribution requested.
package usgs

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"shield/internal/domain"
	"shield/internal/fetch"
	"shield/internal/ingest"
	"shield/internal/severity"
)

const (
	// ID is the source key in the sources table.
	ID = "usgs"
	// FeedURL is the M2.5+ past-day summary feed.
	FeedURL = "https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/2.5_day.geojson"
	// PollInterval matches the feed's one-minute regeneration.
	PollInterval = time.Minute
)

// Source is the USGS adapter.
type Source struct {
	url    string
	client *fetch.Client
	store  ingest.EventStore
}

// New builds the adapter on the production feed.
func New(client *fetch.Client, store ingest.EventStore) *Source {
	return &Source{url: FeedURL, client: client, store: store}
}

// Info implements ingest.Source.
func (*Source) Info() domain.SourceInfo {
	return domain.SourceInfo{
		ID:           ID,
		Name:         "USGS Earthquake Hazards Program",
		URL:          "https://earthquake.usgs.gov/earthquakes/feed/",
		License:      "Public domain (U.S. Government work)",
		Attribution:  "U.S. Geological Survey",
		PollInterval: PollInterval,
		Enabled:      true,
	}
}

// Poll implements ingest.Source.
func (s *Source) Poll(ctx context.Context, v domain.Validators) (ingest.Result, error) {
	resp, err := s.client.Get(ctx, s.url, v)
	if err != nil {
		return ingest.Result{}, err
	}
	if resp.NotModified {
		return ingest.Result{Validators: resp.Validators, NotModified: true}, nil
	}
	events, deleted, err := Parse(resp.Body)
	if err != nil {
		return ingest.Result{}, err
	}
	n, err := s.store.Upsert(ctx, ID, events)
	if err != nil {
		return ingest.Result{}, err
	}
	d, err := s.store.Delete(ctx, ID, deleted)
	if err != nil {
		return ingest.Result{}, err
	}
	return ingest.Result{Validators: resp.Validators, Upserted: n + d}, nil
}

type feed struct {
	Features []struct {
		ID         string `json:"id"`
		Properties struct {
			Mag     *float64 `json:"mag"`
			MagType string   `json:"magType"`
			Place   string   `json:"place"`
			Time    int64    `json:"time"`
			Updated int64    `json:"updated"`
			URL     string   `json:"url"`
			Felt    *int     `json:"felt"`
			CDI     *float64 `json:"cdi"`
			MMI     *float64 `json:"mmi"`
			Alert   *string  `json:"alert"`
			Status  string   `json:"status"`
			Tsunami int      `json:"tsunami"`
			Sig     int      `json:"sig"`
			Net     string   `json:"net"`
			Type    string   `json:"type"`
			Title   string   `json:"title"`
		} `json:"properties"`
		Geometry struct {
			Coordinates []float64 `json:"coordinates"` // lon, lat, depth km
		} `json:"geometry"`
	} `json:"features"`
}

// Parse normalizes a USGS GeoJSON summary feed. deleted lists events USGS
// has retracted (false detections), which the store removes.
//
// Only type "earthquake" is kept: quarry blasts, explosions and other
// non-natural events are not hazards. Events without a magnitude cannot be
// classified and are skipped until USGS assigns one.
func Parse(body []byte) (events []domain.Event, deleted []string, err error) {
	var f feed
	if err := json.Unmarshal(body, &f); err != nil {
		return nil, nil, fmt.Errorf("usgs: decode: %w", err)
	}
	for i := range f.Features {
		ft := &f.Features[i]
		p := ft.Properties
		if ft.ID == "" || p.Type != "earthquake" {
			continue
		}
		if p.Status == "deleted" {
			deleted = append(deleted, ft.ID)
			continue
		}
		if p.Mag == nil || len(ft.Geometry.Coordinates) < 2 {
			continue
		}
		lon, lat := ft.Geometry.Coordinates[0], ft.Geometry.Coordinates[1]

		alert := ""
		if p.Alert != nil {
			alert = *p.Alert
		}
		tsunami := p.Tsunami == 1
		origin := time.UnixMilli(p.Time).UTC()

		attrs := map[string]any{
			"mag":          *p.Mag,
			"magType":      p.MagType,
			"place":        p.Place,
			"sig":          p.Sig,
			"tsunami":      tsunami,
			"reviewStatus": p.Status, // automatic | reviewed
			"network":      p.Net,
		}
		if len(ft.Geometry.Coordinates) > 2 {
			attrs["depthKm"] = ft.Geometry.Coordinates[2]
		}
		if alert != "" {
			attrs["pagerAlert"] = alert
		}
		if p.Felt != nil {
			attrs["feltReports"] = *p.Felt
		}
		if p.CDI != nil {
			attrs["cdi"] = *p.CDI
		}
		if p.MMI != nil {
			attrs["mmi"] = *p.MMI
		}

		title := p.Title
		if title == "" {
			title = fmt.Sprintf("M %.1f - %s", *p.Mag, p.Place)
		}
		events = append(events, domain.Event{
			SourceEventID:  ft.ID,
			Type:           domain.TypeEarthquake,
			Kind:           domain.KindObserved,
			Status:         domain.StatusActive,
			Severity:       severity.Earthquake(*p.Mag, alert, tsunami).String(),
			SourceSeverity: sourceSeverity(*p.Mag, p.MagType, alert, tsunami),
			Title:          title,
			Summary:        p.Place,
			Geometry:       domain.PointGeometry(lon, lat),
			StartedAt:      &origin,
			ObservedAt:     origin,
			UpdatedAt:      time.UnixMilli(p.Updated).UTC(),
			URL:            p.URL,
			Attrs:          attrs,
		})
	}
	return events, deleted, nil
}

// sourceSeverity is USGS's own description, shown next to Shield's level.
func sourceSeverity(mag float64, magType, alert string, tsunami bool) string {
	parts := []string{strings.TrimSpace(fmt.Sprintf("M%.1f %s", mag, magType))}
	if alert != "" {
		parts = append(parts, "PAGER "+alert)
	}
	if tsunami {
		parts = append(parts, "tsunami flag")
	}
	return strings.Join(parts, ", ")
}
